class Web3MintingClient {
  constructor(ctx) {
    this.ctx = ctx;
  }

  /** GET /skus?project=...&search=... — confirms a SKU exists before minting it. */
  skus({ project, search }) {
    return this.ctx.get(`/skus?project=${encodeURIComponent(project)}&search=${encodeURIComponent(search)}`);
  }

  /** POST /claim/address — mints an NFT (ERC-721 if amount is omitted/"1", else ERC-1155). */
  claimAddress({ address, sku, project, amount }) {
    const data = { address, sku, project };
    if (amount !== undefined) data.amount = amount;
    return this.ctx.post('/claim/address', { data });
  }

  /** POST /claim/erc20 — mints a fungible token (e.g. USDC). Not an NFT route. */
  claimErc20({ address, sku, project, amount }) {
    return this.ctx.post('/claim/erc20', { data: { address, sku, project, amount } });
  }
}

module.exports = Web3MintingClient;"
