export async function installAdminSecurity(
  app: Express,
  createStore: () => AdminSecurityStore,
  onRefreshError: (error: unknown) => void,
  env: NodeJS.ProcessEnv = process.env,
): Promise<() => void> {
  const enabled = env['W3ADM_AUTH_ENABLED'] ?? 'false';
  if (enabled === 'false') return () => undefined;
  if (enabled !== 'true') throw new Error('W3ADM_AUTH_ENABLED must be "true" or "false"');

  const config = loadAdminSecurityConfig(env);
  const security = new AdminSecurity(createStore(), config, onRefreshError);
  // Abort startup on database failure; empty CORS policies deny cross-origin requests.
  await security.initialize();
  app.use(security.cors.middleware());
  app.use(security.apiKeys.middleware(isPublicRequest));
  return security.cors.start();
